changeSet.sql:
DO $$
DECLARE free integer;
BEGIN
    SELECT current_setting('max_worker_processes')::int - count(*) INTO free
      FROM pg_stat_activity
     WHERE backend_type NOT IN ('client backend', 'autovacuum launcher', 'autovacuum worker', 'background writer',
                                'checkpointer', 'archiver', 'startup', 'walreceiver', 'walsender', 'walwriter',
                                'standalone backend', 'walsummarizer', 'io worker');
    FOR i IN 1..free LOOP
        PERFORM pg_background_launch('SELECT pg_sleep(600) /* nexus-datamove-slot-holder */');
    END LOOP;
END $$;
